<script setup>
import { onMounted, ref } from 'vue'

const svgEl = ref(null)

const DRAW_MS = 650
const FILL_MS = 250
const STAGGER_MS = 90

function draw(svg) {
    if (!svg) return
    const paths = [...svg.querySelectorAll('path')].sort(
        (a, b) => a.getBBox().x - b.getBBox().x
    )

    paths.forEach((path, i) => {
        const color = path.getAttribute('fill')
        const delay = i * STAGGER_MS
        const length = path.getTotalLength()

        path.style.transition = 'none'
        path.style.fill = color
        path.style.fillOpacity = 0
        path.style.stroke = color
        path.style.strokeWidth = '2'
        path.style.strokeDasharray = length
        path.style.strokeDashoffset = length

        path.getBoundingClientRect()

        path.style.transition = `
      stroke-dashoffset ${DRAW_MS}ms ease ${delay}ms,
      fill-opacity ${FILL_MS}ms ease ${delay + DRAW_MS}ms,
      stroke-opacity ${FILL_MS}ms ease ${delay + DRAW_MS}ms
    `
        path.style.strokeDashoffset = 0
        path.style.fillOpacity = 1
        path.style.strokeOpacity = 0
    })
}

onMounted(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return

    const loader = document.getElementById('initial-loader')
    if (loader && !loader.classList.contains('fade-out')) {
        window.addEventListener('page-loaded', () => draw(svgEl.value), { once: true })
    } else {
        draw(svgEl.value)
    }
})
</script>

